CREATE TABLE IF NOT EXISTS UnitPromotions_YieldFromScouting(PromotionType, YieldType, Yield);
INSERT OR REPLACE INTO UnitPromotions_YieldFromScouting (PromotionType, YieldType, Yield)
SELECT PromotionType || '_NATIONALISM', YieldType, Yield
FROM UnitPromotions_YieldFromScouting WHERE PromotionType IN (SELECT PromotionType FROM Policy_FreePromotions WHERE PolicyType IN (SELECT Type FROM Policies WHERE PolicyBranchType IS NOT NULL AND Level = 0)) OR PromotionType IN (SELECT PromotionType FROM Policy_FreePromotionUnitCombats WHERE PolicyType IN (SELECT Type FROM Policies WHERE PolicyBranchType IS NOT NULL AND Level = 0));
